        "items": [
          "The poem 'Beautiful Hands' was written by Ellen M. H. Gates.",
          "Beautiful hands are not those that are soft and white.",
          "Beautiful hands are those that do noble, good and true deeds.",
          "Hands that help the poor and the sick are beautiful.",
          "Hands that work hard for the family are beautiful.",
          "Hands that write, build and serve others are beautiful.",
          "The beauty of hands lies in their work, not in their looks.",
          "The poem teaches us to use our hands for good deeds.",
          "We should help others with our hands whenever we can.",
          "A life of service makes our hands and our hearts beautiful."
        ]
