                    "q": "Which chores did our last Prophet (PBUH) use to do?",
                    "a": "Our last Prophet (PBUH) repaired his own shoes, mended and washed his clothes, and swept his room. When the mosque was being built in Medina, he carried mud and building material, just like all others. During the battle of Khandaq, he joined his companions in digging the trench outside Medina."
