                    "q": ", Situation 1: Seek and offer advice. I am having a real problem with my sibling. I like to keep my room clean and tidy, but my brother/sister is very messy. He/she throws his/her clothes and stuff all over the place and every time I have to clean up the mess created by him/her. What should I do?",
                    "a": "Model dialogue for Situation 1 (messy sibling): A: I am having a real problem with my sibling. I like to keep my room clean and tidy, but my brother is very messy. He throws his clothes and stuff all over the place and every time I have to clean up the mess created by him. What should I do? B: You should talk to him politely and tell him how you feel. If I were you, I would make a rule that each of us keeps his own things in his own place. You should also praise him when he keeps things tidy."
