                    "a": "Model dialogue for Situation 3 (want to be an artist): A: I am a student of class X. I want to be an artist. Hala is famous for its rich artistic work, and I want to add to this rich heritage. My problem is that my parents want me to go to a medical college and be a doctor. I do not want to hurt my parents' feelings. How can I convince them? B: You should respectfully tell your parents about your talent and your interest in art. If I were you, I would show them your artwork and ask them to give you a chance. You should also promise them that you will work hard and make them proud."
