                "label": "Exercise 6",
                "items": [
                  {
                    "q": "Write a summary of the poem 'King Bruce and the Spider'.",
                    "a": "The poem 'King Bruce and the Spider' is written by Eliza Cook. It tells us how King Bruce of Scotland learnt the lesson of never giving up from a little spider. In the first three verses, King Bruce is sad and in despair. He has tried again and again to do a great deed for his people, but he has failed every time, so he decides to give up. In the next verses, a spider drops down in front of him. The king watches it trying to climb up to its cobweb home. The spider climbs, slips and falls down again and again, but it does not give up. It tries nine times and fails, yet it keeps trying. In the last verses, the spider climbs steadily, inch by inch, and at last reaches its home. The king is filled with joy and cries, 'Bravo! bravo! He conquered, and why should not I?' He decides to try once more, and this time he does not fail. In all, the poem teaches us that we should never lose hope. If we keep trying with patience and courage, we will succeed in the end. The moral of the poem is: Try, try, try again."
                  }
                ]
