                    "q": "Read the poem 'Little Things' by Julia Carney and write a summary by following the guidelines. (Model summary.)",
                    "a": "The poem 'Little Things' is a simple children's song by Julia Carney. It explains that even little things are important. In the first stanza, the poet says that little drops of water and little grains of sand make the mighty ocean and the pleasant land. In the second stanza, the poet says that little deeds of kindness and little words of love make our world an Eden, like the Heaven above. In all, the poem teaches us that small things have great value. Little acts of kindness and love can make the world a happy and beautiful place."
