                    "q": ". Write a summary of the story and an alternative ending.",
                    "a": "Summary: Mr. Aziz and his family planned a holiday in a village with his brother Mr. Karim's family. They had waited for this trip for nearly three months. They travelled by train to Patni station and hired a van to reach a rented house near the fields. The porter and the van driver both asked them, 'Are you sure?' because the people of the area believed the house was haunted. Mr. Aziz did not believe in ghosts. The families liked the big, airy house and enjoyed the clean air and fresh vegetables of the village. A week passed happily. Then, on the seventh night, someone pulled Mr. Karim's blanket and his bed. Nobody believed him. The next evening, a head jumped and blocked his way during his walk. On the last night, an empty chair moved by itself in front of all four adults. They all started screaming. Then Mr. Karim woke up. It was all a bad dream. He thanked Mrs. Karim for waking him up.\n\nAlternative ending: In the morning, Mr. Karim told his family about his bad dream. They all laughed, but Mr. Aziz said, 'Let us still be careful. We will stay in a hotel in the town instead of that lonely house.' So the two families changed their plan and spent their ten days in a comfortable hotel near the town. They visited the village during the day, enjoyed the fields and the fresh food, and returned to the hotel every evening. They had a happy and safe holiday, and Mr. Karim never had a bad dream again."
