              {
                "label": "Exercise 2",
                "items": [
                  {
                    "q": "Write a letter to the Editor on: Stagnant Water on Roads and Streets.",
                    "a": "7 November 2026\nHyderabad\nThe Editor,\nDaily Dawn,\nKarachi.\nDear Sir,\nI want to draw your attention to the problem of stagnant water on roads and streets in our area. After every rain, water stands on the roads for many days. It becomes dirty and gives out a bad smell. Mosquitoes breed in it and spread diseases like malaria and dengue. Children and old people find it very hard to walk on these roads, and vehicles also get damaged.\nThe concerned authorities should take notice of this problem. The drainage system should be cleaned and repaired, and the stagnant water should be removed at once. I hope the authorities will act quickly to solve this problem.\nYours faithfully,\nA Student"
                  },
                  {
                    "q": "Write a letter to the Editor on: Unannounced Load-Shedding.",
                    "a": "7 November 2026\nHyderabad\nThe Editor,\nDaily Dawn,\nKarachi.\nDear Sir,\nThrough your newspaper, I want to highlight the problem of unannounced load-shedding in our area. Electricity goes off many times a day without any notice. Students cannot study at night, and their preparation for exams suffers badly. Shops, offices, and small factories also cannot work properly.\nThe power supply company should inform the people about the load-shedding schedule in advance and reduce its duration. I hope the authorities will take notice of this problem and provide relief to the people.\nYours faithfully,\nA Student"
                  }
                ]
              }
