                    "a": "Nadeem went to his boss and asked if he would get a promotion that year. His boss replied that he would. Nadeem asked when he would get it. His boss said that he would, but on one condition. Nadeem asked what that was. The boss asked if he could answer some questions. Nadeem asked if he answered correctly, he would get the promotion. The boss confirmed it and asked if he should ask him three easy questions or one difficult question. Nadeem asked if he could give him some time to think. The boss gave him two minutes to decide. Nadeem asked if the difficult question was very difficult. The boss replied that it would depend on what he thought was difficult. Nadeem asked what if he could not answer. Then he further asked if he would get another chance. The boss replied in the negative. Nadeem thought for a minute and agreed to be asked one difficult question. The boss asked if he was sure. Nadeem asked if he had a choice. The boss said that he could try the three easy questions. Nadeem said that he would like to answer the difficult question. So, the boss asked what had come first, day or night. Nadeem thought for a minute and replied that day had come first. The boss asked how he knew. Nadeem asked if he had not answered one question as per their agreement. The boss was pleased with his quick thinking and gave him immediate promotion."
