            "name": "Writing",
            "exercises": [
              {
                "label": "Exercise 1",
                "items": [
                  {
                    "q": ". Write an argumentative essay on one of the following topics: 1. Wearing uniforms should not be compulsory in schools 2. All the students should be promoted to the next class without exams 3. Teachers should punish students who do not do their work properly 4. Students should not be allowed to bring mobile phones to school 5. Gardening should be made a compulsory subject in all schools",
                    "a": "Model essay — Students should not be allowed to bring mobile phones to school. Paragraph 1 (Introduction): Mobile phones have become a part of our lives, but should students be allowed to bring them to school? I believe that students should not be allowed to bring mobile phones to school, because they disturb studies and create many problems. Paragraph 2 (Argument 1): Firstly, mobile phones distract students from their studies. Students play games, watch videos and chat with friends during lessons instead of listening to the teacher. As a result, their marks fall. Paragraph 3 (Argument 2): Secondly, mobile phones are used for cheating in exams and for bullying other students. Some students take photographs and videos without permission, which harms others. Paragraph 4 (Opposite viewpoint): Some people say that mobile phones are useful for safety and for contacting parents in an emergency. However, this problem can be solved easily: parents can contact the school office, and the school can inform the parents. Students do not need to carry phones themselves. Paragraph 5 (Conclusion): In conclusion, mobile phones do more harm than good in schools. If students are not allowed to bring them, they will study better, and schools will be safer and more peaceful."
                  }
                ]
              },
              {
                "label": "Exercise 2",
                "items": [
                  {
                    "q": ". Now, work individually and write an argumentative essay on any one of the above topics but not the one on which you have already written.",
                    "a": "Model essay — Wearing uniforms should not be compulsory in schools. Paragraph 1 (Introduction): Many schools make uniforms compulsory for students. I believe that wearing uniforms should not be compulsory in schools, because students should have the freedom to wear what they like. Paragraph 2 (Argument 1): Firstly, uniforms are expensive for poor families. Parents have to buy new uniforms every year, which is a burden. If students wear their own clothes, families can save money. Paragraph 3 (Argument 2): Secondly, uniforms do not make students equal or disciplined. Discipline comes from good teaching and good manners, not from clothes. Students can be disciplined in their own clothes too. Paragraph 4 (Opposite viewpoint): Some people say that uniforms create unity and remove the difference between rich and poor students. However, students can still see the difference in shoes, bags and watches. Uniforms do not remove this difference. Paragraph 5 (Conclusion): In conclusion, uniforms should not be forced on students. Schools should allow students to wear neat and decent clothes of their own choice."
                  }
                ]
              }
            ],
