                "q": "Construct grouped frequency table of the educational levels (current class of study) of 20 students going to a country tour from a school. The educational levels are: VIII, X, X, VIII, VI, IX, X, IX, X, VIII, VII, VIII, VI, X, VI, V, IV, VII, IX, IX."
