                "q": "The mode of transport used by 20 students to attend a language course were noted as given below. Construct grouped frequency table with percentage frequencies.\nWalk, Walk, Bike, Bus, Car, Walk, Bike, Walk, Walk, Bus\nCar, Bus, Car, Walk, Walk, Bus, Car, Car, Bus, Bus"
