                "a": "(i) Diagonal = 6.5 cm, width = 2.5 cm. Let the length be l cm.\nBy Pythagoras' theorem: l² + (2.5)² = (6.5)²\nl² = 42.25 − 6.25 = 36\nl = 6 cm. So the correct option is (c) 6cm.\n(ii) Check each set with the converse of Pythagoras' theorem (longest side squared = sum of squares of the other two):\n(a) 3² + 4² = 9 + 16 = 25 = 5² ✓\n(b) 2² + 3² = 4 + 9 = 13 ≠ 16 = 4² ✗\n(c) 5² + 6² = 25 + 36 = 61 ≠ 49 = 7² ✗\n(d) 4² + 5² = 16 + 25 = 41 ≠ 36 = 6² ✗\nSo the correct option is (a) 3, 4, 5.\n(iii) In any triangle the greatest angle is opposite the longest side. In a right-angled triangle the hypotenuse is the longest side and it is opposite the right angle, 90°, which is the greatest angle.\nSo the correct option is (b) 90°.\n(iv) In a right-angled triangle the hypotenuse is the side opposite the right angle.\nSo the correct option is (b) Right angle.\n(v) If c is the largest side (the hypotenuse), Pythagoras' theorem gives c² = a² + b².\nSo the correct option is (a) c² = a² + b².\n(vi) The two sides 5 cm and 12 cm are the legs of the right triangle, so the hypotenuse = √(5² + 12²) = √(25 + 144) = √169 = 13 cm.\nSo the correct option is (d) 13.\n(vii) Let each of the equal sides be x cm. By Pythagoras' theorem: x² + x² = (3√2)²\n2x² = 18\nx² = 9, so x = 3 cm.\nSo the correct option is (c) 3cm.\n∴ Answers: (i) (c), (ii) (a), (iii) (b), (iv) (b), (v) (a), (vi) (d), (vii) (c).",
                "q": "Encircle the correct option.\n(i) Diagonal of a rectangle measures 6.5cm. If its width is 2.5cm, its length is (a) 9cm (b) 4cm (c) 6cm (d) 3cm\n(ii) Which of the following are the sides of a right angled triangle? (a) 3, 4, 5 (b) 2, 3, 4 (c) 5, 6, 7 (d) 4, 5, 6\n(iii) In a right angled triangle the greatest angle is (a) 100° (b) 90° (c) 80° (d) 110°\n(iv) In a right angled triangle hypotenuse is opposite side to (a) Acute angle (b) Right angle (c) Obtuse angle (d) None\n(v) If a, b, c are sides of right angled triangle, with c is the larger side, then (a) c² = a² + b² (b) b² = c² + a² (c) a² = b² + c² (d) c² = a² − b²\n(vi) If 5cm and 12cm are two sides of a right angled triangle, then hypotenuse is (a) 16 (b) 15 (c) 14 (d) 13\n(vii) If hypotenuse of an isosceles right-angled triangle is 3√2 cm, then each of other side is of length (a) 2cm (b) 5cm (c) 3cm (d) 1cm"
