                "a": "In △ABC, DE ∥ AB, with D on BC and E on AC.\nBy Theorem 24.1 (a line parallel to one side of a triangle divides the other two sides proportionally):\nmCE/mAE = mCD/mBD\nmCE/5 = 12/6\nmCE/5 = 2\nmCE = 10 cm\n∴ mCE = 10 cm.",
