                "a": "In △ABC, PQ ∥ BC, with P on AB and Q on AC.\nBy Theorem 24.1:\nmAP/mPB = mAQ/mQC\n(5x − 3)/2 = (2x + 1)/3\nCross-multiplying:\n3(5x − 3) = 2(2x + 1)\n15x − 9 = 4x + 2\n15x − 4x = 2 + 9\n11x = 11\nx = 1\n∴ x = 1.",
