                "a": "Given: △ABC is right-angled at B. BD is drawn perpendicular to the hypotenuse AC, dividing △ABC into △ADB and △BDC.\nTo prove: Each of △ADB and △BDC is similar to the original triangle △ABC.\nProof:\nConsider △ADB and △ABC:\n∠A is common to both triangles.\n∠ADB = 90° (since BD ⊥ AC) and ∠ABC = 90° (given), so ∠ADB = ∠ABC.\nHence △ADB ~ △ABC by AA similarity (two angles of one triangle equal to two angles of the other).\nConsider △BDC and △ABC:\n∠C is common to both triangles.\n∠BDC = 90° (since BD ⊥ AC) and ∠ABC = 90° (given), so ∠BDC = ∠ABC.\nHence △BDC ~ △ABC by AA similarity.\nTherefore each of the two triangles into which the perpendicular divides the right triangle is similar to the original triangle. Q.E.D.",
                "q": "In a right triangle the perpendicular drawn from the right angle to the hypotenuse divides the triangle into two triangles. Prove that each of these triangles is similar to the original one."
