                "a": "(i) In a proportion a : b = c : d, the product of the means (b × c) equals the product of the extremes (a × d). So the correct option is (d) product.\n(ii) In an equilateral triangle all angles are 60°, so any two equilateral triangles are equiangular and hence always similar. So the correct option is (d) equilateral.\n(iii) The symbol of similarity of triangles is ~. So the correct option is (c) ~.\n(iv) By Theorem 24.1, a line parallel to one side of a triangle divides the other two sides in the same ratio. If one side is divided in 2 : 3, the other side is also divided in 2 : 3. So the correct option is (b) 2:3.\n(v) By Theorem 24.2 (converse of Theorem 24.1), if a line intersects two sides of a triangle in the same ratio, it is parallel to the third side. So the correct option is (a) parallel.\n(vi) By the angle bisector theorem (Theorem 24.3), the bisector of ∠A divides BC in the ratio AB : AC = 6 : 8 = 3 : 4. So the correct option is (b) 3:4.\n(vii) In an equilateral triangle the bisector of a vertex angle is also the median to the opposite side, so it bisects the opposite side, i.e. divides it in the ratio 1 : 1. So the correct option is (c) 1:1.\n(viii) By Theorem 24.4, the corresponding sides of two similar triangles are proportional. So the correct option is (c) proportional.\n(ix) The ratio of the areas of two similar triangles equals the square of the ratio of their corresponding sides: (5/7)² = 25/49. So the correct option is (d) 25:49.\n(x) The ratio of corresponding sides is the square root of the ratio of areas: √(36/121) = 6/11. So the correct option is (b) 6:11.\n(xi) The ratio of areas is the square of the ratio of sides: (2/x)² = 4/9, so 2/x = 2/3 (x is a length, so positive), giving x = 3. So the correct option is (a) 3.\n(xii) Two equilateral triangles are always equiangular (all angles 60°), so they are always similar. So the correct option is (b) similar.\n∴ Answers: (i) (d), (ii) (d), (iii) (c), (iv) (b), (v) (a), (vi) (b), (vii) (c), (viii) (c), (ix) (d), (x) (b), (xi) (a), (xii) (b).",
                "q": "Tick the correct option.\n(i) In a proportion, the product of means is equal to ______ of extremes. (a) sum (b) difference (c) quotient (d) product\n(ii) ______ triangles are always similar. (a) right (b) scalene (c) acute angled (d) equilateral\n(iii) The symbol of similarity of triangles is ______. (a) = (b) ≅ (c) ~ (d) ↔\n(iv) If a line parallel to base of a triangle and divides one side in 2:3 then it will divide other side in ______. (a) 3:2 (b) 2:3 (c) 2:6 (d) 5:3\n(v) If a line intersects two sides of a triangle in same ratio then it is ______ to other side. (a) parallel (b) non-parallel (c) coincident (d) all of these\n(vi) In △ABC, the bisector of ∠A divides BC in ratio ______ if mAB = 6cm and mAC = 8cm. (a) 5:8 (b) 3:4 (c) 1:1 (d) 5:7\n(vii) The bisector of an angle of equilateral triangle divides the opposite side in ______. (a) 2:3 (b) 3:2 (c) 1:1 (d) 5:2\n(viii) The corresponding sides of two similar triangles are ______. (a) equal (b) un-equal (c) proportional (d) None of these\n(ix) If the ratio of two corresponding sides of similar triangle is 5:7 then ratio of their areas is equal to ______. (a) 5:7 (b) 7:5 (c) 25:7 (d) 25:49\n(x) If the ratio of areas of two similar triangles is 36:121 then the ratio of its corresponding sides will be ______. (a) 6:10 (b) 6:11 (c) 11:6 (d) 10:6\n(xi) If the ratio of corresponding sides of similar triangles is 2:x and that of areas is 4:9 then x = ______. (a) 3 (b) -3 (c) both a and b (d) none of these\n(xii) Two equilateral triangles are also ______. (a) congruent (b) similar (c) proportional (d) equivalent"
