                "a": "When two chords AB and CD of a circle intersect at P, the products of the lengths of the segments of each chord are equal (Example 1 of this unit):\nmAP × mPB = mCP × mPD\n(a) In the figure, mAP = x, mPB = x, mCP = 2 and mPD = 10.\nx × x = 2 × 10\nx² = 20\nx = √20 = 2√5 (ignoring the negative square root, as length is positive)\n(b) In the figure, mAP = 4, mPB = x, mCP = 3 and mPD = 8.\n4 × x = 3 × 8\n4x = 24\nx = 6\n(c) In the figure, mAP = x, mPB = 12, mCP = 3 and mPD = 20.\nx × 12 = 3 × 20\n12x = 60\nx = 5\n(d) In the figure, mAP = 4.5, mPB = 12, mCP = 5 and mPD = x.\n4.5 × 12 = 5 × x\n54 = 5x\nx = 54/5 = 10.8\n(e) In the figure, mAP = x, mPB = x, mCP = 17 and mPD = 12.\nx × x = 17 × 12\nx² = 204\nx = √204 = 2√51 (ignoring the negative square root, as length is positive)\n(f) In the figure, mAP = 7.2, mPB = x, mCP = 4.5 and mPD = 9.6.\n7.2 × x = 4.5 × 9.6\n7.2x = 43.2\nx = 43.2/7.2 = 6\n∴ (a) 2√5, (b) 6, (c) 5, (d) 10.8, (e) 2√51, (f) 6.",
                "q": "If two chords AB and CD of a circle with centre O intersect at P, find x in the following figures. (a) mAP = x, mPB = x, mCP = 2, mPD = 10. (b) mAP = 4, mPB = x, mCP = 3, mPD = 8. (c) mAP = x, mPB = 12, mCP = 3, mPD = 20. (d) mAP = 4.5, mPB = 12, mCP = 5, mPD = x. (e) mAP = x, mPB = x, mCP = 17, mPD = 12. (f) mAP = 7.2, mPB = x, mCP = 4.5, mPD = 9.6."
